// =====================================================================
//  JUGGERNAUT: BOSS KIT (Script macro, run as GM). Safe to re-run.
//  Generated by tools/court-boss-build (juggernaut-core.js): edit there, then rebuild.
//  Built for his NPC sheet (CR 20 construct, colossus stat block). The runtime is scripts/court/juggernaut.mjs:
//   - Creature type construct (flags.nix-module.creatureType + the sheet's type).
//   - Senses: Blindsight 30 ft, Tremorsense 120 ft (sheet + token detection modes).
//   - Legendary Actions: 3 native pips, refilled at the start of his turn. Charge (1): 30-ft line,
//     2d8 bludgeoning to each creature in it, DC 13 Dex save or Prone. Toss (1): Rock (ranged attack,
//     30 ft) or Creature (melee attack on a Prone creature, Large or smaller, within reach); a hit deals
//     2d8 bludgeoning and knocks the target Prone; a tossed creature lands where the GM picks, within 30 ft.
//   - Legendary Resistance: 3/day (native pips), one prompt on a failed save (succeed / accept).
//   - Aura (30 ft): 1d3 when combat starts and at the start of each of his turns (Tasha's Hideous
//     Laughter DC 13 Wis / Ray of Enfeeblement DC 15 Con / Decaying Mist DC 15 Con), saved by a creature
//     that starts its turn in it.
//   - Lightning Absorption: lightning heals him instead; lightning is taken off his immunities,
//     resistances and vulnerabilities so nothing else changes the amount.
//   - Petrifying Gaze (1/day): Flesh to Stone style, DC 15 Con (3 failures = Petrified, 3 successes = free).
// =====================================================================
const MOD = 'nix-module';
const actor = canvas.tokens.controlled[0]?.actor;
if (!actor) return ui.notifications.warn('Juggernaut boss kit: no actor.');
if (actor.type !== 'npc') return ui.notifications.warn('Juggernaut boss kit: ' + actor.name + ' isn\'t an NPC sheet. This kit is built for his NPC stat block.');
const report = [];
const prev = actor.flags?.[MOD]?.juggernaut ?? {};
const act = (id, type, data) => ({_id: id, type, ...data});
const twoD8 = {number: 2, denomination: 8, bonus: '', types: ['bludgeoning'], custom: {enabled: false, formula: ''}, scaling: {mode: '', number: null, formula: ''}};
const legendary1 = {type: 'legendary', value: 1, override: false, condition: ''};
// Same as his own Smite / Stomp: the pip is spent through an explicit attribute target.
const legactCost = {targets: [{type: 'attribute', target: 'resources.legact.value', value: '1', scaling: {mode: '', formula: ''}}], scaling: {allowed: false, max: ''}};
async function ensureItem(data, match) {
    let it = actor.items.find(match);
    if (it) { await it.update(data); return actor.items.get(it.id); }
    [it] = await actor.createEmbeddedDocuments('Item', [foundry.utils.expandObject(data)]);
    return it;
}
const kindIs = k => i => i.flags?.[MOD]?.juggernautItem === k;

// ---- 1. Creature type --------------------------------------------------------------------
await actor.update({'flags.nix-module.creatureType': 'construct'});
if (actor.system.details?.type && actor.system.details.type.value !== 'construct') await actor.update({'system.details.type.value': 'construct'});
report.push('Creature type: <b>construct</b> (sheet and Nix Fix checks).');

// ---- 2. Senses: sheet + token detection modes ----------------------------------------------
await actor.update({'system.attributes.senses.ranges.blindsight': 30, 'system.attributes.senses.ranges.tremorsense': 120, 'system.attributes.senses.units': 'ft'});
const BLIND = CONFIG.Canvas?.detectionModes?.blindsight ? 'blindsight' : 'senseAll';
const MODES = [{id: BLIND, range: 30, enabled: true}, {id: 'feelTremor', range: 120, enabled: true}];
// Saved token data only (Vision 5e adds modes on the fly that can't be saved). Array on v13; keyed object on v14.
function withModes(source) {
    const dm = source?.detectionModes;
    if (Array.isArray(dm) || dm === undefined) {
        const keep = (dm ?? []).filter(m => m && m.id && Number.isFinite(Number(m.range)) && !MODES.some(x => x.id === m.id))
            .map(m => ({id: m.id, range: Number(m.range), enabled: m.enabled !== false}));
        return {detectionModes: keep.concat(MODES.map(m => ({...m})))};
    }
    return Object.fromEntries(MODES.map(m => ['detectionModes.' + m.id, {range: m.range, enabled: true}]));
}
const protoUpd = withModes(actor._source?.prototypeToken ?? actor.prototypeToken);
await actor.update(Object.fromEntries(Object.entries(protoUpd).map(([k, v]) => ['prototypeToken.' + k, v])));
let placed = 0;
for (const scene of game.scenes ?? []) for (const t of scene.tokens?.filter?.(t => t.actorId === actor.id) ?? []) { await t.update(withModes(t._source ?? t)); placed++; }
report.push('Senses: Blindsight 30 ft, Tremorsense 120 ft (sheet, prototype token' + (placed ? ', ' + placed + ' placed token' + (placed > 1 ? 's' : '') : '') + '; detection modes ' + BLIND + ' 30 / feelTremor 120).');

// ---- 3. Legendary Actions: 3 pips, Charge (1), Toss (1) -----------------------------------
const la0 = actor.system.resources?.legact ?? {};
await actor.update({'system.resources.legact.max': 3, 'system.resources.legact.spent': Math.min(Number(la0.spent) || 0, 3)});
await ensureItem({
    name: 'Charge', type: 'feat', img: 'icons/creatures/magical/construct-iron-stomping-yellow.webp',
    'system.type': {value: 'monster', subtype: ''},
    'system.description.value': '<p><b>Legendary Action (1).</b> ' + actor.name + ' charges in a 30-foot line. Each creature in the line takes 2d8 bludgeoning damage and must succeed on a DC 13 Dexterity saving throw or be knocked Prone. Move his token along the line.</p>',
    'system.activities': {
        nixJuggCharge000: act('nixJuggCharge000', 'save', {name: 'Charge', activation: legendary1, range: {units: 'self', override: true},
            target: {template: {type: 'line', size: '30', width: '5', units: 'ft', contiguous: false, count: ''}, affects: {type: 'creature', count: '', choice: false, special: ''}, prompt: true, override: true},
            save: {ability: ['dex'], dc: {calculation: '', formula: '13'}},
            damage: {onSave: 'full', parts: [twoD8]}, consumption: legactCost, effects: [],
            flags: {[MOD]: {juggernaut: 'charge'}}})
    },
    ['flags.' + MOD + '.juggernautItem']: 'charge'
}, i => kindIs('charge')(i) || /^charge$/i.test(i.name));
const slam = actor.items.find(i => /^slam/i.test(i.name));
const reach = Number(slam?.system.range?.reach ?? slam?.system.activities?.find?.(a => a.type === 'attack')?.range?.reach) || 10;
const toss = (id, name, kind, type, range, text) => act(id, 'attack', {name, activation: legendary1, range: {...range, override: true},
    target: {affects: {type: 'creature', count: '1', choice: false, special: ''}, template: {type: '', units: 'ft'}, prompt: true, override: true},
    attack: {ability: 'str', bonus: '', flat: false, critical: {threshold: null}, type: {value: type, classification: 'weapon'}},
    damage: {includeBase: false, parts: [twoD8]}, consumption: legactCost, effects: [],
    description: {chatFlavor: text}, flags: {[MOD]: {juggernaut: kind}}});
await ensureItem({
    name: 'Toss', type: 'feat', img: 'icons/magic/earth/projectile-boulder-debris.webp',
    'system.type': {value: 'monster', subtype: ''},
    'system.description.value': '<p><b>Legendary Action (1).</b> ' + actor.name + ' throws a rock, or a Prone creature (Large or smaller) within his reach, up to 30 feet. '
        + '<b>Rock:</b> ranged attack against a creature within 30 ft. <b>Creature:</b> melee attack against the Prone creature. On a hit the target takes 2d8 bludgeoning damage and is knocked Prone; '
        + 'a thrown creature lands where the GM picks, within 30 ft. A creature where it lands isn\'t hurt.</p>',
    'system.activities': {
        nixJuggTossRock0: toss('nixJuggTossRock0', 'Toss: Rock', 'tossRock', 'ranged', {value: '30', units: 'ft'}, 'Throws a rock.'),
        nixJuggTossCrea0: toss('nixJuggTossCrea0', 'Toss: Creature', 'tossCreature', 'melee', {value: String(reach), reach, units: 'ft'}, 'Throws a Prone creature (Large or smaller) up to 30 ft.')
    },
    ['flags.' + MOD + '.juggernautItem']: 'toss'
}, i => kindIs('toss')(i) || /^toss$/i.test(i.name));
// His "Legendary Actions" text (D&D Beyond: Smite, Stomp) also lists Charge and Toss; re-runs replace that paragraph.
const laText = actor.items.find(i => i.type === 'feat' && /^legendary actions$/i.test(i.name) && !i.system.activities?.size);
if (laText) {
    const NIX = '<p class="nix-juggernaut">';
    const base = String(laText.system.description?.value ?? '').replace(/<p class="nix-juggernaut">[\s\S]*?<\/p>/g, '');
    await laText.update({'system.description.value': base + NIX + '<strong><em>Charge.</em></strong> 30-foot line: 2d8 bludgeoning to each creature in it, DC 13 Dexterity save or Prone. '
        + '<strong><em>Toss.</em></strong> A rock (ranged attack, 30 ft) or a Prone creature, Large or smaller, within reach (melee attack): 2d8 bludgeoning and Prone; a thrown creature lands up to 30 feet away.</p>'});
}
const otherLA = actor.items.filter(i => !i.flags?.[MOD]?.juggernautItem && i.system.activities?.some?.(a => a.activation?.type === 'legendary')).map(i => i.name);
report.push('Legendary Actions: 3 pips, back at the start of his turn. Charge (1): 30-ft line, 2d8 bludgeoning, DC 13 Dex or Prone. Toss (1): Rock (ranged, 30 ft) or Creature (melee, reach '
    + reach + ' ft, Prone target Large or smaller), 2d8 bludgeoning + Prone, thrown creature lands where you pick within 30 ft.'
    + (otherLA.length ? ' Other Legendary Actions left as they were: ' + otherLA.join(', ') + '.' : ''));

// ---- 4. Legendary Resistance: 3/day + prompt ------------------------------------------------
const LR_MACRO = `
// Nix Fix: Juggernaut Legendary Resistance (save / bonus / 50). One prompt on a failed save with a DC:
// spend a Legendary Resistance pip to succeed, or accept. Runs in Nix Fix (scripts/court/juggernaut.mjs).
const api = game.modules.get('nix-module')?.api?.juggernaut;
if (!api?.legendaryResistance) return;
return await api.legendaryResistance(trigger);
`;
const res0 = actor.system.resources?.legres ?? {};
await actor.update({'system.resources.legres.max': 3, 'system.resources.legres.spent': Math.min(Number(res0.spent) || 0, 3)});
const lrItems = actor.items.filter(i => i.flags?.[MOD]?.legendaryResistance || /^legendary resistance/i.test(i.name));
const lrData = it => {
    const emb = (it?.flags?.['chris-premades']?.embeddedMacros ?? []).filter(m => m.name !== 'Legendary Resistance (Juggernaut)');
    const desc = String(it?.system.description?.value ?? '').replace(/\b[2-9]\s*\/\s*day\b/gi, '3/Day').replace(/\(\s*[2-9]\s*\/\s*day\s*\)/gi, '(3/Day)');
    return {
        name: 'Legendary Resistance (3/Day)',
        'system.description.value': desc || '<p>If ' + actor.name + ' fails a saving throw, he can choose to succeed instead (3/day). Nix Fix asks on every failed save while he has one left.</p>',
        'flags.chris-premades.embeddedMacros': emb.concat([{name: 'Legendary Resistance (Juggernaut)', type: 'save', pass: 'bonus', priority: 50, macro: LR_MACRO}]),
        ['flags.' + MOD + '.legendaryResistance']: true,
        ...(it?.system.uses?.max ? {'system.uses.max': '3', 'system.uses.spent': Math.min(Number(it.system.uses.spent) || 0, 3)} : {})
    };
};
if (lrItems.length) for (const [n, it] of lrItems.entries()) {
    if (n === 0) await it.update(lrData(it));
    else await it.update({'flags.chris-premades.embeddedMacros': (it.flags?.['chris-premades']?.embeddedMacros ?? []).filter(m => m.name !== 'Legendary Resistance (Juggernaut)'), ['flags.' + MOD + '.legendaryResistance']: false});
} else await actor.createEmbeddedDocuments('Item', [foundry.utils.expandObject({type: 'feat', img: 'icons/creatures/magical/construct-golem-stone-blue.webp', 'system.type': {value: 'monster', subtype: ''}, ...lrData(null)})]);
report.push('Legendary Resistance: 3/day (was ' + (Number(res0.max) || 0) + '), one prompt on a failed save (succeed / accept).');

// ---- 5. Petrifying Gaze: 1/day, Flesh to Stone style -----------------------------------------
const gaze0 = actor.items.find(i => kindIs('gaze')(i) || /^petrifying gaze/i.test(i.name));
await ensureItem({
    name: 'Petrifying Gaze (1/Day)', type: 'feat', img: 'icons/magic/perception/eye-ringed-glow-angry-large-teal.webp',
    'system.type': {value: 'monster', subtype: ''},
    'system.description.value': '<p>' + actor.name + ' fixes his gaze on one creature he can see within 60 feet. It makes a DC 15 Constitution saving throw. On a failure it is Restrained as its flesh begins to harden, '
        + 'and it repeats the save at the end of each of its turns. After three failed saves it is Petrified (until cured, e.g. Greater Restoration); after three successful saves the effect ends.</p>',
    'system.uses': {max: '1', spent: Math.min(Number(gaze0?.system.uses?.spent) || 0, 1), recovery: [{period: 'lr', type: 'recoverAll'}]},
    'system.activities': {
        nixJuggGaze00000: act('nixJuggGaze00000', 'save', {name: 'Petrifying Gaze', activation: {type: 'action', value: 1, override: false, condition: ''},
            range: {value: '60', units: 'ft', override: true}, target: {affects: {type: 'creature', count: '1', choice: false, special: ''}, template: {type: '', units: 'ft'}, prompt: true, override: true},
            save: {ability: ['con'], dc: {calculation: '', formula: '15'}}, damage: {onSave: 'none', parts: []},
            consumption: {targets: [{type: 'itemUses', target: '', value: '1'}], scaling: {allowed: false}}, effects: [],
            flags: {[MOD]: {juggernaut: 'gaze'}}})
    },
    ['flags.' + MOD + '.juggernautItem']: 'gaze'
}, i => kindIs('gaze')(i) || /^petrifying gaze/i.test(i.name));
report.push('Petrifying Gaze (1/day, action, 60 ft): DC 15 Con; a failure Restrains, then a save at the end of each of its turns: 3 failures = Petrified, 3 successes = free.');

// ---- 6. Lightning Absorption ----------------------------------------------------------------
const stripped = [];
const tr = actor._source?.system?.traits ?? actor.system.traits ?? {};
for (const k of ['di', 'dr', 'dv']) {
    const v = Array.from(tr[k]?.value ?? []);
    if (v.includes('lightning')) { await actor.update({['system.traits.' + k + '.value']: v.filter(x => x !== 'lightning')}); stripped.push({di: 'immunity', dr: 'resistance', dv: 'vulnerability'}[k]); }
}
if (tr.da && Object.prototype.hasOwnProperty.call(tr.da, 'lightning')) { await actor.update({'system.traits.da.-=lightning': null}); stripped.push('Midi absorption'); }
const effTraits = [];
for (const e of [...actor.effects, ...actor.items.contents.flatMap(i => Array.from(i.effects ?? []).filter(x => x.transfer))]) {
    const ch = e.system?.changes ?? e.changes ?? [];
    if (ch.some(c => /^system\.traits\.(di|dr|dv|da)\b/.test(c.key ?? '') && /lightning/i.test(String(c.value)) || /absorption\.lightning/.test(c.key ?? ''))) effTraits.push(e.name);
}
await ensureItem({
    name: 'Lightning Absorption', type: 'feat', img: 'icons/magic/lightning/bolt-strike-blue.webp',
    'system.type': {value: 'monster', subtype: ''},
    'system.description.value': '<p>Whenever ' + actor.name + ' is subjected to lightning damage, he takes no damage and instead regains a number of hit points equal to the lightning damage dealt.</p>',
    ['flags.' + MOD + '.juggernautItem']: 'lightning'
}, kindIs('lightning'));
report.push('Lightning Absorption: lightning heals him by the amount (Nix Fix damage hook).' + (stripped.length ? ' Taken off the sheet so it doesn\'t stack: lightning ' + stripped.join(', ') + '.' : ' No lightning immunity / resistance on the sheet.')
    + (effTraits.length ? ' <b>Check these effects</b> (they change lightning damage too): ' + effTraits.join(', ') + '.' : ''));

// ---- 7. Aura ---------------------------------------------------------------------------------
await ensureItem({
    name: 'Shifting Aura', type: 'feat', img: 'icons/magic/unholy/hand-claw-fog-green.webp',
    'system.type': {value: 'monster', subtype: ''},
    'system.description.value': '<p>' + actor.name + ' radiates a 30-foot aura. When combat starts and at the start of each of his turns, roll 1d3 for the aura that is active (the same number keeps it). '
        + 'It affects creatures other than him while he has at least 1 hit point. A creature that starts its turn in the aura makes the save:</p><ol>'
        + '<li><b>Tasha\'s Hideous Laughter.</b> DC 13 Wisdom save or it laughs: Incapacitated for that turn and Prone until the start of its next turn.</li>'
        + '<li><b>Ray of Enfeeblement.</b> DC 15 Constitution save or disadvantage on Constitution saves until the start of its next turn.</li>'
        + '<li><b>Decaying Mist.</b> DC 15 Constitution save or it can\'t regain hit points until the start of its next turn. Plants in the aura wither and die.</li></ol>'
        + '<p>The active aura shows on his token. Nix Fix rolls it and asks for the saves.</p>',
    ['flags.' + MOD + '.juggernautItem']: 'aura'
}, kindIs('aura'));
report.push('Aura (30 ft): 1d3 rolled to chat when combat starts and at the start of each of his turns; the active aura shows on his token; saves at the start of each creature\'s turn in it.');

// ---- 8. Flags -----------------------------------------------------------------------------------
await actor.update({['flags.' + MOD + '.juggernaut']: {version: 1, radius: 30, gazeDc: 15, tossRange: 30, absorbLightning: true,
    dcs: {laughter: 13, enfeeble: 15, mist: 15}, aura: prev.aura ?? 0, auraCombat: prev.auraCombat ?? null}});
// Shared boss runtime (boss.mjs): refills his Legendary Action pips at the start of his turn. No regeneration, no lair.
await actor.update({['flags.' + MOD + '.boss']: {version: 1, phase2: false, ascendedThisRest: false, legendaryItem: null, lairScenes: [],
    legendaryBase: 3, legendaryLair: 3, regen: false, radiantTaken: 0}});
if (!game.modules.get(MOD)?.api?.juggernaut) report.push('<b>Nix Fix\'s runtime isn\'t running</b> (reload the world): the aura, Lightning Absorption, Legendary Resistance prompt, Toss landing and the Gaze saves need it.');

await ChatMessage.create({whisper: [game.user.id], content: '<b>Nix Fix: ' + actor.name + ' boss kit</b><ul><li>' + report.join('</li><li>') + '</li></ul>'});
